  if (search.get('id') || search.get('code')) return search.get('id') || search.get('code')
  if (current.id || current.code) return current.id || current.code
  try { const root = typeof window === 'undefined' ? {} : JSON.parse(window.localStorage.getItem('beefcare-ui-demo') || '{}'); const legacy = root.account?.['selected-voucher']; return legacy?.id || legacy?.code } catch { return undefined }
