const canEdit = (role?: ScreenRole) => role === 'owner' || role === 'manager'
const roleText = (role?: ScreenRole) => role === 'owner' ? 'Chủ trại' : role === 'manager' ? 'Quản lý' : 'Kỹ thuật viên'

function Shell({ screen, role, children, actions }: { screen: ScreenDefinition; role?: ScreenRole; children: ReactNode; actions?: ReactNode }) {
  return <div className="herd-advanced-ui flex min-w-0 w-full flex-col gap-6"><PageHeader title={screen.viTitle} sub={`Dữ liệu hồ sơ · vai trò ${roleText(role || screen.roles[0])}`} badge={<FixtureNotice />}>{actions}</PageHeader>{children}</div>
}
function StateGate({ state, children }: { state?: ReviewState; children: ReactNode }) {
  if (state === 'loading') return <LoadingState label="Đang tải dữ liệu phiếu nhập…" />
  if (state === 'error') return <InlineMessage tone="err" title="Không tải được dữ liệu">Kiểm tra kết nối và thử tải lại màn hình.</InlineMessage>
  return <>{children}</>
}
function roleGuard(role: ScreenRole | undefined, allowed: ScreenRole[]) { return role ? allowed.includes(role) : false }

