  const navigate = useNavigate(); const [search] = useSearchParams(); const kind = (search.get('kind') || 'ENTRY').toUpperCase(); const isEntry = kind === 'ENTRY'; const returnTarget = search.get('returnTarget') || (isEntry ? `/ui/scr-106?id=${encodeURIComponent(selectedId(search) || '')}` : kind === 'EXIT' ? '/ui/scr-110' : '/ui/scr-112'); const [vouchers] = useState(loadVouchers); const voucher = isEntry ? vouchers.find((row) => row.id === selectedId(search) || row.code === selectedId(search)) || vouchers[0] : undefined; const [amount, setAmount] = useState(''); const [date, setDate] = useState(today()); const [method, setMethod] = useState<'CASH' | 'BANK'>('BANK'); const [reference, setReference] = useState(''); const [note, setNote] = useState(''); const [attachment, setAttachment] = useState(''); const [error, setError] = useState(''); const paid = voucher?.payments.filter((payment) => payment.status !== 'VOIDED').reduce((sum, payment) => sum + payment.amount, 0) || 0; const outstanding = Math.max((voucher?.totalAmount || 0) + (voucher?.header?.transportFee || 0) - paid, 0)
