  const transactions = read<Array<Record<string, any>>>('void-transactions', [])
  const prepared = transactions.filter((transaction) => transaction.status === 'PREPARED' && transaction.plan)
  if (!prepared.length) return
  let vouchers: EntryVoucher[] = []
  try { vouchers = JSON.parse(window.localStorage.getItem(`${STORE}.vouchers`) || '[]') as EntryVoucher[] } catch { vouchers = [] }
